/**
 * AgentIntent - Output envelope for AI decision-making
 *
 * Contains move, aim, and fire instructions that the AgentController
 * consumes to drive agent behavior. Intents produce AgentIntent objects
 * each frame to communicate their desired actions.
 *
 * **Usage**
 *
 * ```js
 * // In an Intent's update() method:
 * update(body, state, memory, delta) {
 *   const intent = new AgentIntent();
 *
 *   // Set movement
 *   intent.move.destination = targetPosition;
 *   intent.move.speed = 'run';
 *
 *   // Set aiming
 *   intent.aim.target = enemyPosition;
 *   intent.aim.smoothing = 0.2;
 *
 *   // Set firing
 *   intent.fire.trigger = true;
 *   intent.fire.mode = 'single';
 *
 *   return intent;
 * }
 * ```
 *
 * @module @three-blocks/pro/ai/AgentIntent
 * @class AgentIntent
 * @short Move/aim/fire output envelope
 * @category AI
 * @tags AI, Intent, Movement, Combat
 */
export class AgentIntent {
    /**
     * Movement instructions.
     * @type {MoveIntent}
     */
    move: MoveIntent;
    /**
     * Aiming instructions.
     * @type {AimIntent}
     */
    aim: AimIntent;
    /**
     * Firing instructions.
     * @type {FireIntent}
     */
    fire: FireIntent;
    /**
     * Reset all intents to default values.
     *
     * @returns {AgentIntent} This instance for chaining.
     */
    reset(): AgentIntent;
    /**
     * Copy values from another AgentIntent.
     *
     * @param {AgentIntent} other - The intent to copy from.
     * @returns {AgentIntent} This instance for chaining.
     */
    copy(other: AgentIntent): AgentIntent;
}
/**
 * MoveIntent - Movement instructions
 *
 * Specifies where and how the agent should move.
 *
 * @class MoveIntent
 */
export class MoveIntent {
    /**
     * Target destination position (world coordinates).
     * @type {{ x: number, y: number, z: number }|null}
     */
    destination: {
        x: number;
        y: number;
        z: number;
    } | null;
    /**
     * Desired velocity vector (alternative to destination).
     * @type {{ x: number, y: number, z: number }|null}
     */
    velocity: {
        x: number;
        y: number;
        z: number;
    } | null;
    /**
     * Movement speed mode.
     * @type {'walk'|'run'|'sprint'}
     */
    speed: "walk" | "run" | "sprint";
    /**
     * Enable strafing (sideways movement while facing target).
     * @type {boolean}
     */
    strafe: boolean;
    /**
     * Stop moving and hold position.
     * @type {boolean}
     */
    stop: boolean;
    /**
     * Reset to default values.
     *
     * @returns {MoveIntent} This instance for chaining.
     */
    reset(): MoveIntent;
    /**
     * Copy values from another MoveIntent.
     *
     * @param {MoveIntent} other - The intent to copy from.
     * @returns {MoveIntent} This instance for chaining.
     */
    copy(other: MoveIntent): MoveIntent;
}
/**
 * AimIntent - Aiming instructions
 *
 * Specifies where the agent should aim/look.
 *
 * @class AimIntent
 */
export class AimIntent {
    /**
     * Target position to aim at (world coordinates).
     * @type {{ x: number, y: number, z: number }|null}
     */
    target: {
        x: number;
        y: number;
        z: number;
    } | null;
    /**
     * Rotation smoothing factor (0 = instant, 1 = no rotation).
     * @type {number}
     */
    smoothing: number;
    /**
     * Enable target leading (predict target movement).
     * @type {boolean}
     */
    leadTarget: boolean;
    /**
     * Override movement-based rotation with aim direction.
     * @type {boolean}
     */
    overrideMovementRotation: boolean;
    /**
     * Reset to default values.
     *
     * @returns {AimIntent} This instance for chaining.
     */
    reset(): AimIntent;
    /**
     * Copy values from another AimIntent.
     *
     * @param {AimIntent} other - The intent to copy from.
     * @returns {AimIntent} This instance for chaining.
     */
    copy(other: AimIntent): AimIntent;
}
/**
 * FireIntent - Firing instructions
 *
 * Specifies when and how the agent should fire.
 *
 * @class FireIntent
 */
export class FireIntent {
    /**
     * Fire this frame.
     * @type {boolean}
     */
    trigger: boolean;
    /**
     * Firing mode.
     * @type {'single'|'burst'|'auto'}
     */
    mode: "single" | "burst" | "auto";
    /**
     * Number of shots per burst (for burst mode).
     * @type {number}
     */
    burstCount: number;
    /**
     * Reset to default values.
     *
     * @returns {FireIntent} This instance for chaining.
     */
    reset(): FireIntent;
    /**
     * Copy values from another FireIntent.
     *
     * @param {FireIntent} other - The intent to copy from.
     * @returns {FireIntent} This instance for chaining.
     */
    copy(other: FireIntent): FireIntent;
}
